-- 취선만권 (초 오의): 점점 빨라지는 앞구르기 다섯 바퀴 → 와다다다 주먹 → 술병 내려찍기
-- 앞 47% (= 컷씬 1.6초 / 전체 3.4초) 동안 일곱 바퀴 구른다. 구른 각도는 -2520도로 남아 있어야 거꾸로 풀리지 않는다
A.soju_rolls = {
	{ t = 0, j = { W = { 20, 0, 0 }, N = { 20, 0, 0 }, RS = { 60, 0, 20 }, RE = { 120, 0, 0 }, LS = { 60, 0, -20 }, LE = { 120, 0, 0 }, RH = { 60, 0, 0 }, RK = { -100, 0, 0 }, LH = { 60, 0, 0 }, LK = { -100, 0, 0 }, R = { -20, 0, 0, 0, -1.4, 0 } } },
}
do
	local CUT = 1.6 / 3.4
	local TUCK = { W = { -40, 0, 0 }, N = { -40, 0, 0 }, RS = { 120, 0, 30 }, RE = { 70, 0, 0 }, LS = { 120, 0, -30 }, LE = { 70, 0, 0 }, RH = { 110, 0, 0 }, RK = { -135, 0, 0 }, LH = { 110, 0, 0 }, LK = { -135, 0, 0 } }
	for k = 1, 14 do
		-- 각도가 시간의 제곱으로 늘어난다 (갈수록 빨라진다)
		local j = table.clone(TUCK)
		j.R = { -180 * k, 0, 0, 0, -1.5, 0 }
		table.insert(A.soju_rolls, { t = CUT * math.sqrt(k / 14), j = j })
	end
	local spin = -2520
	-- 벌떡 일어나 주먹을 퍼붓는다 (좌우 번갈아 스무 번, 몸은 비틀비틀)
	local n = 20
	for i = 1, n do
		local r = i % 2 == 1
		local t = CUT + 0.02 + (0.94 - CUT - 0.02) * (i - 1) / (n - 1)
		local sway = math.sin(i * 1.3) * 12
		table.insert(A.soju_rolls, { t = t, e = "snap", j = {
			W = { 0, r and 40 or -40, sway * 0.5 }, N = { 0, r and -25 or 25, sway },
			RS = r and { 92, 0, 0 } or { 140, 0, 20 }, RE = r and { 0, 0, 0 } or { 70, 0, 0 },
			LS = r and { 40, 0, -20 } or { 92, 0, 0 }, LE = r and { 100, 0, 0 } or { 0, 0, 0 },
			RH = { 25, 0, 10 }, RK = { -35, 0, 0 }, LH = { -20, 0, -10 }, LK = { -25, 0, 0 },
			R = { spin - 6, r and 6 or -6, sway, 0, -0.55, r and -0.4 or -0.2 },
		} })
	end
	table.insert(A.soju_rolls, { t = 0.96, j = { W = { -25, 0, 0 }, N = { -25, 0, 0 }, RS = { 178, 0, 10 }, RE = { 20, 0, 0 }, LS = { 100, 0, -40 }, LE = { 30, 0, 0 }, R = { spin + 10, 0, 0, 0, 0.1, 0 } } })
	table.insert(A.soju_rolls, { t = 0.99, e = "snap", j = { W = { 45, 0, 0 }, N = { 20, 0, 0 }, RS = { 40, 0, 0 }, RE = { 0, 0, 0 }, LS = { 30, 0, -50 }, LE = { 20, 0, 0 }, RH = { 40, 0, 10 }, RK = { -80, 0, 0 }, LK = { -70, 0, 0 }, R = { spin - 20, 0, 0, 0, -1.6, -1.0 } } })
	table.insert(A.soju_rolls, { t = 1, j = { W = { 45, 0, 0 }, N = { 20, 0, 0 }, RS = { 40, 0, 0 }, RE = { 0, 0, 0 }, LS = { 30, 0, -50 }, LE = { 20, 0, 0 }, RH = { 40, 0, 10 }, RK = { -80, 0, 0 }, LK = { -70, 0, 0 }, R = { spin - 20, 0, 0, 0, -1.6, -1.0 } } })
end
-- 취선승천권: 술병째 올려 치며 한 바퀴 솟는다
