	{ t = 0, j = { W = { 15, -30, 0 }, RS = { 20, 0, 30 }, RE = { 60, 0, 0 }, LS = { 40, 0, -40 }, LE = { 40, 0, 0 }, RK = { -60, 0, 0 }, LK = { -50, 0, 0 }, R = { -10, 0, 10, 0, -1.0, 0 } } },
