local REAP_UP = { W = { -20, -25, 0 }, N = { 18, 25, 0 }, RS = { 150, 0, 35 }, RE = { 70, 0, 0 }, LS = { 55, 0, -40 }, LE = { 50, 0, 0 }, RH = { -25, 0, 18 }, LH = { 35, 0, -16 }, RK = { -50, 0, 0 }, LK = { -60, 0, 0 } }
-- 끝 자세 (돈 만큼 몸 방향을 남겨 둔다: 거꾸로 풀리지 않게)
local function reapEnd(yaw: number?): Joints
	local j = table.clone(REAP_UP)
	j.R = { -10, yaw or 0, 0, 0, -1.1, 0 }
	return j
end
