	{ t = 0, j = { W = { 30, 0, 0 }, N = { 20, 0, 0 }, RS = { 40, 0, 30 }, RE = { 90, 0, 0 }, LS = { 30, 0, -30 }, LE = { 90, 0, 0 }, RH = { 80, 0, 0 }, RK = { -130, 0, 0 }, LH = { -10, 0, 0 }, LK = { -100, 0, 0 }, R = { -10, 0, 0, 0, -2.0, 0 } } },
