-- 3.4판 초·성하신권 (오른손에 별 지팡이)
-- 지팡이는 손에서 비스듬히 꽂혀 있어 (화면이 그린다), 어깨 + 팔꿈치가 110도쯤이면 곧게 선다.
-- 그보다 적으면 끝이 앞으로 눕고 (20도면 앞으로 수평), 많으면 뒤로 눕는다
------------------------------------------------------------------------
local STAFF = { W = { 0, -20, 0 }, N = { -4, 20, 0 }, RS = { 40, 0, 15 }, RE = { 70, 0, 0 }, LS = { 55, 0, -28 }, LE = { 35, 0, 0 }, RH = { -12, 0, 10 }, LH = { 20, 0, -8 }, RK = { -28, 0, 0 }, LK = { -24, 0, 0 } }
local function staffEnd(yaw: number?): Joints
	local j = table.clone(STAFF)
	j.R = { 0, yaw or 0, 0, 0, -0.4, 0 }
	return j
end
-- 높은 오른쪽에서 왼쪽 아래로 지팡이를 비스듬히 휘두른다
