local STAFF_SPIN = { W = { -5, -20, 0 }, N = { 0, 15, 0 }, RS = { 20, 0, 80 }, RE = { 0, 0, 0 }, LS = { 40, 0, -70 }, LE = { 20, 0, 0 }, RH = { -15, 0, 14 }, LH = { 20, 0, -14 }, RK = { -35, 0, 0 }, LK = { -35, 0, 0 } }
local function staffSpin(yaw: number, fwd: number?): Joints
	local j = table.clone(STAFF_SPIN)
	j.R = { 0, yaw, 0, 0, -0.6, fwd or 0 }
	return j
end
